// Compile a portable payload from twapp's /intake-to-ado skill
// into an ADO REST 'JSON Patch' body.
//
// Incoming (from webhook body):
//   feat_id:        "FEAT-006"
//   work_item_type: "User Story" | "Bug"
//   title:          string
//   description:    string (HTML)
//   acceptance:     string (HTML <ul>)
//   tags:           string[] (semicolon-joined by ADO)
//   assignee:       email
//   area:           "App"
//   iteration:      "App"
//
// Output:
//   patch: JSON-Patch array shape ADO expects
//   type:  URL-encoded work-item-type ('$User%20Story' or '$Bug')

const body = $input.first().json.body || $input.first().json;

const wiType = (body.work_item_type || 'User Story').trim();
const typePath = wiType === 'Bug' ? '$Bug' : '$User%20Story';

const tagsStr = Array.isArray(body.tags) ? body.tags.join('; ') : (body.tags || '');

const patch = [
  { op: 'add', path: '/fields/System.Title',        value: body.title },
  { op: 'add', path: '/fields/System.Description',  value: body.description || '' },
  { op: 'add', path: '/fields/Microsoft.VSTS.Common.AcceptanceCriteria', value: body.acceptance || '' },
  { op: 'add', path: '/fields/System.Tags',         value: tagsStr },
  { op: 'add', path: '/fields/System.AreaPath',     value: body.area || 'App' },
  { op: 'add', path: '/fields/System.IterationPath',value: body.iteration || 'App' }
];

if (body.assignee) {
  patch.push({ op: 'add', path: '/fields/System.AssignedTo', value: body.assignee });
}

return [{ json: {
  patch,
  type: typePath,
  org: $env.AZDO_ORG_TRUSTWORKS || 'Trustworks',
  project: $env.AZDO_PROJECT_TRUSTWORKS || 'App',
  feat_id: body.feat_id
}}];

// Translate ADO's response into the {id, url} shape the twapp skill
// expects. On upstream failure, propagate the status so the skill can
// map it to a user-facing message.

const r = $input.first().json;
const status = r.statusCode || 0;

if (status >= 200 && status < 300) {
  const wi = r.body || r;
  const org = $('Compile ADO JSON Patch').item.json.org;
  const project = $('Compile ADO JSON Patch').item.json.project;
  const url = (wi._links && wi._links.html && wi._links.html.href)
              || `https://dev.azure.com/${org}/${project}/_workitems/edit/${wi.id}`;
  return [{ json: {
    status: 200,
    id: wi.id,
    url,
    feat_id: $('Compile ADO JSON Patch').item.json.feat_id
  }}];
}

// Non-2xx: forward the ADO status + a scrubbed excerpt of the body.
// Do NOT include auth headers or full response headers.
let excerpt = '';
try {
  excerpt = typeof r.body === 'string' ? r.body : JSON.stringify(r.body);
} catch (e) { excerpt = ''; }
if (excerpt.length > 500) excerpt = excerpt.slice(0, 500) + '...';

return [{ json: {
  status: 502,
  error: 'upstream-ado',
  upstream_status: status,
  upstream_excerpt: excerpt,
  feat_id: $('Compile ADO JSON Patch').item.json.feat_id
}}];
